package rw.isurafashion.service;
import rw.isurafashion.model.User; import rw.isurafashion.repository.UserRepository; import rw.isurafashion.security.JwtService; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class AuthService {
 private final UserRepository repo; private final JwtService jwt; private final BCryptPasswordEncoder enc=new BCryptPasswordEncoder();
 public AuthService(UserRepository r,JwtService j){repo=r;jwt=j;}
 public Map<String,Object> register(String email,String password,String phone){if(!password.matches("(?=.*[A-Za-z])(?=.*\\d).{8,}"))throw new IllegalArgumentException("Password must be at least 8 characters with a letter and number"); if(!phone.matches("07\\d{8}"))throw new IllegalArgumentException("Use a Rwandan mobile number like 0781234567"); if(repo.findByEmailIgnoreCase(email).isPresent())throw new IllegalArgumentException("Email is already registered"); User u=new User();u.setEmail(email.toLowerCase().trim());u.setPasswordHash(enc.encode(password));u.setPhone(phone);repo.save(u);return token(u);}
 public Map<String,Object> login(String email,String password){User u=repo.findByEmailIgnoreCase(email).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(u.isLocked()&&u.getLockedUntil()!=null&&Instant.now().isBefore(u.getLockedUntil()))throw new IllegalArgumentException("Account is temporarily locked. Try again later.");if(u.isLocked()){u.setLocked(false);u.setFailedLogins(0);u.setLockedUntil(null);}if(!enc.matches(password,u.getPasswordHash())){u.setFailedLogins(u.getFailedLogins()+1);if(u.getFailedLogins()>=3){u.setLocked(true);u.setLockedUntil(Instant.now().plus(Duration.ofMinutes(30)));}repo.save(u);throw new IllegalArgumentException("Invalid email or password");}u.setFailedLogins(0);repo.save(u);return token(u);}
 private Map<String,Object> token(User u){return Map.of("token",jwt.create(u.getId(),u.getEmail(),u.getRole()),"user",Map.of("id",u.getId(),"email",u.getEmail(),"role",u.getRole(),"loyaltyTier",u.getLoyaltyTier()));}
}
